const entities = $input.first().json.entities;
const entity_type = $input.first().json.entity_type;

function ensureArray(v) {
  if (v == null) return [];
  return Array.isArray(v) ? v : [v];
}

function pickInto(target, source, keys, rename = {}) {
  for (const key of keys) {
    if (source[key] != null && source[key] !== '') {
      const outKey = rename[key] || key;
      if (!target[outKey]) target[outKey] = [];
      target[outKey].push(...ensureArray(source[key]));
    }
  }
}

const general_info = {};
const sanctions = {};
const urls = {};
const relationships_info = {};

// ==========================================
// 1. Aleph
// ==========================================
if (entities.Aleph?.length > 0) {
  general_info.aleph = {};
  sanctions.aleph = {};
  urls.aleph = { sourceUrl: [] };

  entities.Aleph.forEach(item => {
    const props = item.properties || {};
    const top = item;
    const rename = { collection_summary: 'summary' };
    const commonKeys = ['name','country','website','sector','jurisdiction','permId','idNumber','alias','kppCode','ogrnCode','incorporationDate','address','status','legalForm','phone','innCode','taxNumber','collection_summary'];

    pickInto(general_info.aleph, top, commonKeys, rename);
    pickInto(general_info.aleph, props, commonKeys, rename);

    const personKeys = ['birthDate','birthPlace','birthCountry','nationality','gender','citizenship','firstName','lastName','middleName','fatherName','secondName','position','education','religion','wikidataId'];
    pickInto(general_info.aleph, props, personKeys);

    pickInto(sanctions.aleph, top, ['notes','topics']);
    pickInto(sanctions.aleph, props, ['notes','topics']);

    if (Array.isArray(props.sanctions)) {
      if (!sanctions.aleph.sanctions) sanctions.aleph.sanctions = [];
      sanctions.aleph.sanctions.push(...props.sanctions);
    }

    if (props.sourceUrl) urls.aleph.sourceUrl.push(...ensureArray(props.sourceUrl));
    else if (top.sourceUrl) urls.aleph.sourceUrl.push(...ensureArray(top.sourceUrl));
  });
}

// ==========================================
// 2. OpenSanctions
// ==========================================
if (entities.OpenSanctions?.length > 0) {
  general_info.open_sanctions = {};
  sanctions.open_sanctions = {};
  urls.open_sanctions = { sourceUrl: [] };

  entities.OpenSanctions.forEach(item => {
    const props = item.properties || {};
    const commonKeys = ['name','jurisdiction','registrationNumber','incorporationDate','legalForm','address','phone','country','idNumber','website'];
    pickInto(general_info.open_sanctions, props, commonKeys);

    const personKeys = ['birthDate','birthPlace','birthCountry','nationality','gender','citizenship','firstName','lastName','middleName','fatherName','secondName','position','education','religion','wikidataId','alias'];
    pickInto(general_info.open_sanctions, props, personKeys);

    pickInto(sanctions.open_sanctions, props, ['notes','topics']);
    if (Array.isArray(props.sanctions)) {
      if (!sanctions.open_sanctions.sanctions) sanctions.open_sanctions.sanctions = [];
      sanctions.open_sanctions.sanctions.push(...props.sanctions);
    }
    if (props.sourceUrl) urls.open_sanctions.sourceUrl.push(...ensureArray(props.sourceUrl));
  });
}

// ==========================================
// 3. OpenCorporates
// ==========================================
if (entities.OpenCorporates?.length > 0) {
  general_info.open_corporates = {};
  urls.open_corporates = { sourceUrl: [] };

  entities.OpenCorporates.forEach(item => {
    const data = item.company || item.officer || item;
    const rename = { company_number: 'registrationNumber', jurisdiction_code: 'jurisdiction', current_status: 'status', incorporation_date: 'incorporationDate', registered_address_in_full: 'address', company_type: 'legalForm', registry_url: 'sourceUrl' };

    pickInto(general_info.open_corporates, data, ['name', 'company_number', 'jurisdiction_code', 'incorporation_date', 'current_status', 'company_type', 'registered_address_in_full', 'industry_codes', 'dissolution_date'], rename);

    if (entity_type !== 'Company') pickInto(general_info.open_corporates, data, ['name', 'position', 'start_date', 'end_date', 'nationality', 'occupation'], rename);

    if (data.opencorporates_url) urls.open_corporates.sourceUrl.push(data.opencorporates_url);
    if (data.registry_url) urls.open_corporates.sourceUrl.push(data.registry_url);
  });
}

// ==========================================
// 4. North Data (DETAIL UPDATE)
// ==========================================
if (entities.NorthData?.length > 0) {
  general_info.north_data = {};
  urls.north_data = { sourceUrl: [] };
  const relations = {}; 

  entities.NorthData.forEach(item => {
    // --- General Info ---
    const rename = {
        city: 'address', foundingDate: 'incorporationDate', date: 'incorporationDate',
        registerId: 'registrationNumber', uid: 'taxNumber', vatId: 'taxNumber',
        legalForm: 'legalForm', status: 'status', email: 'email', phone: 'phone', url: 'website'
    };
    const companyKeys = [
        'name', 'city', 'address', 'zipCode', 'foundingDate', 'date',
        'registerId', 'legalForm', 'status', 'email', 'phone', 'vatId'
    ];

    // 1. Извлекаем originalSubject (ПО ВАШЕМУ ЗАПРОСУ)
    if (item.originalSubject) {
        if (!general_info.north_data.originalSubject) general_info.north_data.originalSubject = [];
        general_info.north_data.originalSubject.push(item.originalSubject);
    }

    // 2. Обработка имени
    if (item.name && typeof item.name === 'object' && item.name.name) {
        if (!general_info.north_data.name) general_info.north_data.name = [];
        general_info.north_data.name.push(item.name.name);
    } else {
        pickInto(general_info.north_data, item, ['name'], rename);
    }

    pickInto(general_info.north_data, item, companyKeys, rename);

    // 3. Адрес основного объекта
    if (item.address && typeof item.address === 'object') {
        const a = item.address;
        const fullAddr = a.formattedValue || [a.street, a.postalCode, a.city, a.country].filter(Boolean).join(', ');
        if (fullAddr) {
             if (!general_info.north_data.address) general_info.north_data.address = [];
             general_info.north_data.address.push(fullAddr);
        }
    }

    if (item.northDataUrl) urls.north_data.sourceUrl.push(item.northDataUrl);

    // --- RELATIONSHIPS (DETAILED) ---
    // Функция для создания детального объекта связи
    const addRel = (category, relObj) => {
        if (!relations[category]) relations[category] = [];

        // Сущность может быть компанией или персоной
        const ent = relObj.company || relObj.person || {};

        // A. Name & Legal Form
        let nameVal = "Unknown";
        let lfVal = "";

        if (ent.name && typeof ent.name === 'object') {
            nameVal = ent.name.name || "";
            lfVal = ent.name.legalForm || "";
        } else if (ent.name) {
            nameVal = ent.name;
        } else if (ent.firstName || ent.lastName) {
            nameVal = [ent.title, ent.firstName, ent.lastName].filter(Boolean).join(' ');
        }

        // B. Address (используем formattedValue если есть)
        let addrVal = "";
        if (ent.address && typeof ent.address === 'object') {
            addrVal = ent.address.formattedValue || [ent.address.street, ent.address.city, ent.address.country].filter(Boolean).join(', ');
        } else if (typeof ent.address === 'string') {
            addrVal = ent.address;
        }

        // C. Roles
        let rolesVal = relObj.description || "";
        if (Array.isArray(relObj.roles) && relObj.roles.length > 0) {
            // Собираем типы ролей через запятую
            const rolesList = relObj.roles.map(r => r.name || r.type).filter(Boolean);
            if (rolesList.length > 0) rolesVal = rolesList.join(', ');
        }
        if (!rolesVal) rolesVal = "Related";

        // Собираем объект
        const relEntry = {
            name: nameVal,
            role: rolesVal,
            status: ent.status || "Unknown",
            legalForm: lfVal,
            address: addrVal,
            northDataUrl: ent.northDataUrl || ""
        };

        relations[category].push(relEntry);
    };

    // Собираем компании
    if (item.relatedCompanies && Array.isArray(item.relatedCompanies.items)) {
        item.relatedCompanies.items.forEach(rel => {
            const desc = (rel.description || "").toLowerCase();
            let cat = 'related_companies';
            if (desc.includes('parent') || desc.includes('owner') || desc.includes('shareholder')) cat = 'shareholders_parents';
            else if (desc.includes('subsidiary') || desc.includes('child')) cat = 'subsidiaries';
            addRel(cat, rel);
        });
    }

    // Собираем персон
    if (item.relatedPersons && Array.isArray(item.relatedPersons.items)) {
        item.relatedPersons.items.forEach(rel => {
            addRel('management_and_owners', rel);
        });
    }
  });

  if (Object.keys(relations).length > 0) {
      relationships_info.north_data = relations;
  }
}

// Cleanup
for (const dict of [general_info, sanctions, urls, relationships_info]) {
  for (const k of Object.keys(dict)) {
