function uniq(arr) {
  const seen = new Set();
  const out = [];
  for (const v of (arr || [])) {
    const x = typeof v === 'string' ? v.trim() : v;
    const key = typeof x === 'string' ? x.toLowerCase() : JSON.stringify(x);
    if (!seen.has(key)) { seen.add(key); out.push(x); }
  }
  return out;
}

function normCountry(arr) {
  return uniq((arr || []).map(c => typeof c === 'string' ? c.trim().toUpperCase() : c));
}

function dedupDict(dict, normalizeCountry=false) {
  for (const k of Object.keys(dict)) {
    if (k === 'sanctions') continue; // объектные санкции не трогаем
    dict[k] = (normalizeCountry && k === 'country') ? normCountry(dict[k]) : uniq(dict[k]);
  }
}

function capArrays(dict, cap=50) {
  for (const k of Object.keys(dict)) {
    if (Array.isArray(dict[k]) && dict[k].length > cap) dict[k] = dict[k].slice(0, cap);
  }
}

function removeEmptySources(dict) {
  for (const k of Object.keys(dict)) {
    if (!dict[k] || Object.keys(dict[k]).length === 0) delete dict[k];
  }
}

function trimLongText(arr, maxLen=1500) {
  return (arr || []).map(v => typeof v === 'string' && v.length > maxLen ? (v.slice(0, maxLen) + '…') : v);
}

function reorder(obj, order) {
  const out = {};
  for (const k of order) if (k in obj) out[k] = obj[k];
  for (const k of Object.keys(obj)) if (!(k in out)) out[k] = obj[k];
  return out;
}

