  if (sanc?.notes) sanc.notes = trimLongText(sanc.notes, 1500);
}

// 3) Лимиты на длину массивов (LLM-friendly)
for (const src of ['aleph','open_sanctions']) {
  if (split.split_general_info_entities[src]) capArrays(split.split_general_info_entities[src], 50);
  if (split.split_sanctions_entities[src]) capArrays(split.split_sanctions_entities[src], 50);
  if (split.split_urls_entities[src]) capArrays(split.split_urls_entities[src], 50);
}

// 4) Удаляем пустые источники
