// 2) Аккуратный многошаговый парсер без "ломающих" замен
function deepParse(value, maxPasses = 6) {
  let v = value;

  // убираем BOM, если вдруг есть
  const stripBOM = s => (typeof s === 'string' ? s.replace(/^\uFEFF/, '') : s);

  for (let i = 0; i < maxPasses; i++) {
    if (v && typeof v === 'object') return v;
    if (typeof v !== 'string') return v;

    let s = stripBOM(v).trim();

    // если это строковый JSON (в кавычках) — сначала распакуем строку
    if ((s.startsWith('"') && s.endsWith('"'))) {
      try {
        v = JSON.parse(s); // превращаем в обычную строку
        continue;          // и идём на следующий проход
      } catch (e) {
        // падать не спешим — попробуем почистить управ.символы
      }
    }

    // попытка парсить как объект/массив и т.п.
    try {
      v = JSON.parse(s);
      continue;
    } catch (e1) {
      // НЕ делаем \\n -> \n и т.п. — это и ломало JSON ранее!

      // Попытка 2: экранировать СЫРЫЕ управляющие символы (0x00–0x1F), если они затесались
      // Это безопасно: мы не изменяем уже корректные \n, \t, т.п., а только реальные ctrl-символы
      const sanitized = s.replace(/[\u0000-\u001F]/g, ch => {
        const code = ch.charCodeAt(0).toString(16).padStart(2, '0');
        return '\\u00' + code;
      });

      // Попытка 3: починить ОДИНОЧНЫЕ обратные слеши, не образующие валидный escape
      // Пример: "C:\path\to\file" -> "C:\\path\\to\\file"
      // Регекс находит '\', за которым НЕ идёт один из допустимых esc: ["\/bfnrtu]
      const fixedBackslashes = sanitized.replace(/\\(?!["\/bfnrtu])/g, '\\\\');

      try {
        v = JSON.parse(fixedBackslashes);
        continue;
      } catch (e2) {
        // Попытка 4: если это на самом деле "строка-JSON", попробуем распаковать как строку, а затем ещё раз
        try {
          const asString = JSON.parse('"' + fixedBackslashes.replace(/"/g, '\\"') + '"');
          v = asString;
          continue;
        } catch (e3) {
          throw new Error('Failed to parse JSON content: ' + e2.message);
        }
      }
    }
  }
  return v;
}

const parsed = deepParse(raw);

// 3) Валидация: не зажимайся только под {schema, properties},
