const rawResults = Array.isArray(response) ? response : (response.results || []);

// Если пришел массив с вложенностью (как в вашем примере: [ { results: [...] } ])
// То нужно достать results из первого элемента
let items = [];
if (rawResults.length > 0 && rawResults[0].results) {
    items = rawResults[0].results; 
} else {
    items = rawResults;
}

if (!items || items.length === 0) {
    return [{ json: { northdata_found: false } }];
